const FLAGS=['allies','network','e21_done','vault','altered','evidence','central','outer','shared','harbor','sites','initiated'];
const valid=s=>{if(!s||typeof s!=='object'||Array.isArray(s)||Object.keys(s).some(k=>!['version','episode','flags','journal','hints','distribution','route'].includes(k))||s.version!==1||!['center','carried','outer'].includes(s.distribution)||![null,'bypass','linked'].includes(s.route)||![21,22,23,24,25].includes(s.episode)||!s.flags||typeof s.flags!=='object'||Array.isArray(s.flags)||Object.entries(s.flags).some(([k,v])=>!FLAGS.includes(k)||v!==true)||!Array.isArray(s.journal)||s.journal.length>20||s.journal.some(x=>typeof x!=='string')||!s.hints||typeof s.hints!=='object'||Array.isArray(s.hints)||Object.entries(s.hints).some(([k,v])=>!['21','22','23','24'].includes(k)||!Number.isInteger(v)||v<1||v>2))return false;let f=s.flags,e=s.episode;return !(e<22&&(f.e21_done||f.vault||f.altered||f.evidence||f.shared||f.initiated)||e>=22&&!f.e21_done||e<23&&(f.central||f.outer||f.shared)||e>=23&&!f.evidence||e<24&&(f.harbor||f.sites||f.initiated)||e>=24&&!f.shared||e===25&&!f.initiated||f.evidence&&!(f.vault||f.altered)||e<23&&(s.distribution!=='center'||s.route!==null));};
